using BotFramework.Discord.Commands;using BotFramework.Discord.Routing;using Games.Darts.Application.Services;
namespace Games.Darts.Discord;
public sealed class DartsDiscordHandler(IDartsService service):IDiscordMessageHandler{public bool CanHandle(DiscordMessageContext context)=>DiscordCommand.Is(context,"darts","dart");public async Task HandleAsync(DiscordMessageContext context){var p=DiscordCommand.Parts(context);if(p.Length!=2||!int.TryParse(p[1], System.Globalization.CultureInfo.InvariantCulture, out var amount)||amount<=0){await DiscordCommand.ReplyAsync(context,"Использование: `darts <ставка>`");return;}var face=DiscordCommand.RandomFace(1,6);var r=await service.QuickThrowAsync(DiscordCommand.UserId(context),DiscordCommand.DisplayName(context),DiscordCommand.ScopeId(context),DiscordCommand.SourceId(context),face,amount,context.CancellationToken);await DiscordCommand.ReplyResultAsync(context,r,"Darts: "+face);}}
